async function loadImportHistory() {
  if (state.importHistoryLoading) return;
  state.importHistoryLoading = true;
  try {
    const userId = state.user?.id || "";
    const url = `/api/import-tasks?type=leads&actorUserId=${encodeURIComponent(userId)}`;
    const result = await api(url);
    state.importHistory = result || [];
  } catch (err) {
    state.importHistory = [];
    console.warn("[import-history] load failed", err);
  } finally {
    state.importHistoryLoading = false;
    renderApp();
  }
}

async function analyzeLeadPaste() {
  const rawText = document.getElementById("leadPasteRawText")?.value?.trim() || "";
  if (!rawText) {
    setFlash("warn", "请粘贴内容", "至少输入一段文字");
    renderApp();
    return;
  }
  try {
    const result = await api("/api/leads/parse", {
      method: "POST",
      body: JSON.stringify({ rawText, imageUrls: [] })
    });
    state.leadPasteParsed = result.parsed || {};
    state.leadPasteHits = result.hits || {};
    state.leadPasteRawText = rawText;
    renderApp();
  } catch (err) {
    setFlash("warn", "解析失败", err?.message || "请稍后重试");
    renderApp();
  }
}

function clearLeadPaste() {
  state.leadPasteParsed = null;
  state.leadPasteHits = null;
  state.leadPasteRawText = "";
  const ta = document.getElementById("leadPasteRawText");
  if (ta) ta.value = "";
  renderApp();
}

async function submitLeadPaste(event) {
  event.preventDefault();
  const formData = new FormData(event.currentTarget);
  const contactInfo = String(formData.get("contactInfo") || "").trim();
  if (!contactInfo) {
    setFlash("warn", "联系方式必填", "请补充联系方式后再提交");
    renderApp();
    return;
  }
  const noteParts = [];
  const remark = String(formData.get("remark") || "").trim();
  const statusText = String(formData.get("status") || "").trim();
  const sourcePostKeyword = String(formData.get("sourcePostKeyword") || "").trim();
  const operatorKeyword = String(formData.get("operatorKeyword") || "").trim();
  if (remark) noteParts.push(remark);
  if (statusText) noteParts.push(`[跟进状态] ${statusText}`);
  if (sourcePostKeyword) noteParts.push(`[来源关键词] ${sourcePostKeyword}`);
  if (operatorKeyword) noteParts.push(`[运营关键词] ${operatorKeyword}`);
  const selectedAccountId = String(formData.get("accountId") || "").trim();
  const accountId = selectedAccountId || (Array.isArray(state.accounts) && state.accounts[0]?.id) || "";
  const payload = {
    contactInfo,
    nickname: String(formData.get("nickname") || ""),
    platform: String(formData.get("platform") || "未知"),
    ip: String(formData.get("ip") || ""),
    note: noteParts.join("\n"),
    accountId,
    source: "parsed"
  };
  try {
    await api("/api/leads", { method: "POST", body: JSON.stringify(payload) });
    setFlash("success", "粘贴录入成功", "客资已保存");
    clearLeadPaste();
    state.leadEntryMode = "form";
    await loadData();
    renderApp();
  } catch (err) {
    setFlash("warn", "提交失败", err?.message || "请稍后重试");
    renderApp();
  }
}

async function submitLeadBatchImport() {
  const text = document.getElementById("leadImportRowsInput")?.value?.trim() || "";
  if (!text) {
    setFlash("warn", "请粘贴数据", "至少粘贴一行");
    renderApp();
    return;
  }
  const rows = text.split(/\r?\n/).map((r) => r.trim()).filter(Boolean);
  try {
    const result = await api("/api/leads/import-paste", {
      method: "POST",
      body: JSON.stringify({ rows, actorUserId: state.user?.id || "" })
    });
    state.leadImportResult = result;
    const success = result?.success ?? result?.successCount ?? 0;
    const fail = result?.fail ?? result?.failCount ?? 0;
    setFlash("success", "导入完成", `成功 ${success} / 失败 ${fail}`);
    await loadData();
    renderApp();
  } catch (err) {
    setFlash("warn", "导入失败", err?.message || "请稍后重试");
    renderApp();
  }
}

function cancelLeadBatchImport() {
  state.leadEntryMode = "form";
  state.leadImportResult = null;
  renderApp();
}


// ===== 客资录入草稿（防闪退恢复） =====
function renderLeadDraftRestorePrompt() {
  const prompt = state.leadDraftRestorePrompt;
  if (!prompt) return "";
  const safeTime = prompt.updatedAtLabel || "-";
  const count = prompt.count || 0;
  return `
    <div id="leadDraftRestoreBanner" style="background:#fff7e6;border:1px solid #ffc069;border-radius:8px;padding:12px 16px;margin-bottom:12px;display:flex;flex-wrap:wrap;justify-content:space-between;align-items:center;gap:8px;">
      <span style="color:#874d00;">检测到 ${count} 条未提交草稿，最近一次更新于 ${safeTime}，是否恢复最近的？</span>
      <span style="display:flex;gap:8px;">
        <button class="primary js-restore-lead-draft" type="button">恢复</button>
        <button class="ghost js-discard-lead-draft" type="button">丢弃</button>
        <button class="ghost js-close-lead-draft-prompt" type="button" aria-label="关闭" style="padding:4px 10px;">×</button>
      </span>
    </div>
  `;
}

function generateLeadDraftId() {
  try {
    if (typeof crypto !== "undefined" && typeof crypto.randomUUID === "function") {
      return crypto.randomUUID();
    }
  } catch (_err) {
    // fallthrough
  }
  return `draft-${Date.now()}-${Math.random().toString(36).slice(2, 10)}`;
}

function debounceLeadDraft(fn, wait) {
  let timer = null;
  return function debounced(...args) {
    if (timer) clearTimeout(timer);
    timer = setTimeout(() => {
      timer = null;
      try { fn.apply(this, args); } catch (err) { console.warn("[lead-draft] debounced call failed", err); }
    }, wait);
  };
}

const _saveLeadDraftDebounced = debounceLeadDraft(() => { saveLeadDraftNow().catch((err) => console.warn("[lead-draft] save failed", err)); }, 1000);

function collectLeadFormSnapshot() {
  const form = document.getElementById("leadForm");
  if (!form) return null;
  const snapshot = {};
  const fields = form.querySelectorAll("input, select, textarea");
  fields.forEach((el) => {
    if (!el.name || el.name === "id" || el.type === "file") return;
    snapshot[el.name] = el.value;
  });
  return snapshot;
}

async function saveLeadDraftNow() {
  if (!state.user?.id) return;
  if (state.editingLeadId) return;
  if (!state.leadDraftId) state.leadDraftId = generateLeadDraftId();
  const snapshot = collectLeadFormSnapshot();
  if (!snapshot) return;
  const imageUrls = [state.pendingLeadCapture].filter(Boolean);
  try {
    await api(`/api/lead-drafts/${state.leadDraftId}`, {
      method: "PUT",
      body: JSON.stringify({
        draftType: "lead",
        contentJson: JSON.stringify(snapshot),
        imageUrls,
        actorUserId: state.user.id
      })
    });
  } catch (err) {
    console.warn("[lead-draft] PUT failed", err);
  }
}

async function fetchLeadDraftsForUser() {
  if (!state.user?.id) return [];
  try {
    const url = `/api/lead-drafts?type=lead&actorUserId=${encodeURIComponent(state.user.id)}`;
    const rows = await api(url);
    return Array.isArray(rows) ? rows : [];
  } catch (err) {
    console.warn("[lead-draft] GET failed", err);
    return [];
  }
}

async function deleteLeadDraftById(id) {
  if (!id || !state.user?.id) return;
  try {
    await api(`/api/lead-drafts/${id}?actorUserId=${encodeURIComponent(state.user.id)}`, { method: "DELETE" });
  } catch (err) {
    console.warn("[lead-draft] DELETE failed", err);
  }
}

let _leadDraftContextInited = false;
function ensureLeadDraftContext() {
  if (state.editingLeadId) return;
  if (_leadDraftContextInited) return;
  _leadDraftContextInited = true;
  state.leadDraftRestorePrompt = null;
  fetchLeadDraftsForUser().then((rows) => {
    const SEVEN_DAYS_MS = 7 * 24 * 60 * 60 * 1000;
    const recent = rows.filter((r) => {
      const t = new Date(r.updatedAt || r.updated_at || 0).getTime();
      return t && (Date.now() - t) < SEVEN_DAYS_MS;
    });
    if (recent.length > 0) {
      const first = recent[0];
      const dt = new Date(first.updatedAt || first.updated_at || Date.now());
      state.leadDraftRestorePrompt = {
        count: recent.length,
        drafts: recent,
        firstDraftId: first.id,
        updatedAtLabel: typeof formatDate === "function" ? formatDate(dt.toISOString()) : dt.toISOString().slice(0, 16).replace("T", " ")
      };
      if (state.currentView === "lead-entry" && !state.editingLeadId) renderApp();
    } else if (!state.leadDraftId) {
      state.leadDraftId = generateLeadDraftId();
    }
  });
}

function resetLeadDraftContext() {
  _leadDraftContextInited = false;
  state.leadDraftRestorePrompt = null;
}

function applyLeadDraftToForm(draft) {
  let content = {};
  try {
    content = draft && draft.contentJson ? JSON.parse(draft.contentJson) : (draft && draft.content_json ? JSON.parse(draft.content_json) : {});
  } catch (err) {
    console.warn("[lead-draft] parse contentJson failed", err);
    content = {};
  }
  // 关键修复：先写到 state._leadFormBuffer，让 renderLeadEntry 用 bufferedEditing 把 value
  // 渲染进 input 模板。仅写 DOM 的话紧跟着的 renderApp() 全量 innerHTML 会覆盖回空。
  state._leadFormBuffer = state._leadFormBuffer || {};
  Object.entries(content).forEach(([name, value]) => {
    if (name === 'captureImage' || name === 'id') return;
    state._leadFormBuffer[name] = value == null ? '' : String(value);
  });
  // 同步现有 DOM（如果存在），但这只是兜底；真正生效靠 buffer + 下次渲染
  const form = document.getElementById("leadForm");
  if (form) {
    Object.entries(content).forEach(([name, value]) => {
      const el = form.querySelector(`[name="${name}"]`);
      if (!el) return;
      if (el.type === "file") return;
      el.value = value == null ? "" : String(value);
    });
  }
  const imageUrls = Array.isArray(draft?.imageUrls) ? draft.imageUrls : Array.isArray(draft?.image_urls) ? draft.image_urls : [];
  state.pendingLeadCapture = imageUrls[0] || null;
  state.leadDraftId = draft?.id || generateLeadDraftId();
}

async function restoreLeadDraft() {
  const prompt = state.leadDraftRestorePrompt;
  if (!prompt) return;
  const draft = (prompt.drafts || [])[0];
  if (!draft) return;
  applyLeadDraftToForm(draft);
  state.leadDraftRestorePrompt = null;
  renderApp();
  setFlash("success", "草稿已恢复", "之前未提交的内容已经填回表单，请检查后再提交。");
}

async function discardLeadDraft() {
  const prompt = state.leadDraftRestorePrompt;
  if (prompt && prompt.firstDraftId) {
    await deleteLeadDraftById(prompt.firstDraftId);
  }
  state.leadDraftRestorePrompt = null;
  state.leadDraftId = generateLeadDraftId();
  state.pendingLeadCapture = null;
  renderApp();
}

function closeLeadDraftPrompt() {
  state.leadDraftRestorePrompt = null;
  if (!state.leadDraftId) state.leadDraftId = generateLeadDraftId();
  renderApp();
}

function bindLeadDraftEvents() {
  const form = document.getElementById("leadForm");
  if (form && !form.dataset.leadDraftBound) {
    form.dataset.leadDraftBound = "1";
    form.addEventListener("input", (e) => {
      if (state.editingLeadId) return;
      // T-17: 实时同步 form 字段到 buffer，确保图片选择/renderApp 不丢已填文本（§11 图片解耦）
      if (!state._leadFormBuffer) state._leadFormBuffer = {};
      const el = e.target;
      if (el && el.name) state._leadFormBuffer[el.name] = el.value;
      _saveLeadDraftDebounced();
    });
  }
  document.querySelector(".js-restore-lead-draft")?.addEventListener("click", () => { restoreLeadDraft(); });
  document.querySelector(".js-discard-lead-draft")?.addEventListener("click", () => { discardLeadDraft(); });
  document.querySelector(".js-close-lead-draft-prompt")?.addEventListener("click", () => { closeLeadDraftPrompt(); });
}


// ===== L3737-L3781 renderLeadForm =====
function renderLeadForm(editing, options = {}) {
  const compact = Boolean(options.compact);
  const selectedAccountId = editing?.accountId || state.accounts[0]?.id || "";
  const availablePosts = getAccountSourcePosts(selectedAccountId);
  const selectedPostId = availablePosts.some((item) => item.id === editing?.postId)
    ? editing?.postId
    : availablePosts[0]?.id || "";
  return `
    <form id="leadForm" class="form-grid form-grid-tight">
      <input type="hidden" name="id" value="${editing?.id || ""}" />
      <input type="hidden" name="captureImageUrl" value="${editing?.captureImageUrl || ""}" />
      <select name="accountId" required>${state.accounts.map((item) => `<option value="${item.id}" ${selectedAccountId === item.id ? "selected" : ""}>${item.accountName} · ${item.platform}</option>`).join("")}</select>
      <select name="postId" id="leadPostSelect" required>
        ${availablePosts.length
          ? availablePosts.map((item) => `<option value="${item.id}" ${selectedPostId === item.id ? "selected" : ""}>${item.title || "未命名作品"} · ${item.postType}</option>`).join("")
          : `<option value="">该账号下暂无作品，请先录入作品</option>`}
      </select>
      <input name="contactInfo" placeholder="联系方式" value="${editing?.contactInfo || ""}" required />
      <input name="ip" placeholder="IP" value="${editing?.ip || ""}" />
      <select name="status"><option ${editing?.status === "新客资" ? "selected" : ""}>新客资</option><option ${editing?.status === "跟进中" ? "selected" : ""}>跟进中</option><option ${editing?.status === "已成交" ? "selected" : ""}>已成交</option><option ${editing?.status === "无效" ? "selected" : ""}>无效</option></select>
      ${
        compact
          ? `<textarea class="full" name="note" rows="3" placeholder="备注">${editing?.note || ""}</textarea>`
          : `
            <input name="dealAmount" placeholder="成交金额" value="${editing?.dealAmount || ""}" />
            <textarea class="full" name="note" rows="3" placeholder="备注">${editing?.note || ""}</textarea>
          `
      }
      <div class="full">
        <label class="muted" for="leadCaptureInput">引流截图</label>
        <input id="leadCaptureInput" name="captureImage" type="file" accept="image/*" />
        ${state.leadCapturePreviewUrl
          ? `<div class="cover-preview-wrap"><span class="muted">当前待上传截图</span><button class="image-trigger image-trigger-inline js-open-image" data-src="${state.leadCapturePreviewUrl}" type="button"><img class="cover-thumb" src="${state.leadCapturePreviewUrl}" alt="待上传引流截图" /></button></div>`
          : editing?.captureImageUrl
            ? `<div class="cover-preview-wrap"><span class="muted">当前引流截图</span><button class="image-trigger image-trigger-inline js-open-image" data-src="${editing.captureImageUrl}" type="button"><img class="cover-thumb" src="${editing.captureImageUrl}" alt="当前引流截图" /></button></div>`
            : ``}
      </div>
      <div class="actions full">
        <button class="primary" type="submit">${editing ? "保存客资" : "提交客资"}</button>
        ${editing ? `<button class="ghost js-cancel-lead" type="button">取消编辑</button>` : ""}
      </div>
    </form>
  `;
}


